import{_ as a,o as t,c as i,a5 as r}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"UI refresh — verification matrix","description":"","frontmatter":{},"headers":[],"relativePath":"feature/media-package-campaign/ui-refresh/test.md","filePath":"feature/media-package-campaign/ui-refresh/test.md"}'),o={name:"feature/media-package-campaign/ui-refresh/test.md"};function n(s,e,d,l,c,p){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="ui-refresh-—-verification-matrix" tabindex="-1">UI refresh — verification matrix <a class="header-anchor" href="#ui-refresh-—-verification-matrix" aria-label="Permalink to &quot;UI refresh — verification matrix&quot;">​</a></h1><h2 id="correction-matrix-—-2026-10-19" tabindex="-1">Correction matrix — 2026-10-19 <a class="header-anchor" href="#correction-matrix-—-2026-10-19" aria-label="Permalink to &quot;Correction matrix — 2026-10-19&quot;">​</a></h2><p>Verify package empty/selected/catalogue/detail/proposal modes and top Change package with unchanged API locks; note/error/count/version/approvals remain visible when relevant. Deliverable name/type/quantity/description/acceptance visually distinct, long text wraps. Help opens with keyboard/touch; no placeholder descriptions dominate cards. Campaign has compact stage header and no duplicated partner link; start+8 weeks, leap/month/year boundaries, missing duration, manual end override and unchanged existing drafts. Task Detail has no approval shortcut. Long-media approval page list/detail must have real scrollHeight&gt;clientHeight, wheel reaches bottom actions/history on desktop/mobile, page horizontal overflow absent. Test vi/en/light/dark and error recovery with fixtures, never mutate shared DB.</p><h3 id="results-—-2026-10-19" tabindex="-1">Results — 2026-10-19 <a class="header-anchor" href="#results-—-2026-10-19" aria-label="Permalink to &quot;Results — 2026-10-19&quot;">​</a></h3><ul><li>27 main browser checks PASS: Client top Change action above fold, agreed duration (8 weeks) distinct from catalogue (2 weeks), help Enter/Escape, catalogue return, deliberate 409 switch failure retains catalogue, successful selection returns to detail, 375/768/1440 no overflow; Manager Campaign start-date suggestion uses agreement duration, manual end preserved, empty end recalculated; real long detail/list scrolling with 70 caption lines and 8 media fixtures. Campaign test draft discarded through application confirmation, not a DB mutation.</li><li>13 additional browser checks PASS: wheel reaches actual bottom at all three widths, approval buttons reachable; dark screenshot each width; browse-only after package lock, English help and labels. Screenshots visually inspected (desktop package groupings and mobile approval bottom). Native date inputs exercised by browser fill; mobile physical-device/touch and all negotiation forms were not fully E2E exercised.</li><li>12 date utility checks PASS: start+8 weeks, leap day/month/year rollover, invalid/empty date, absent/zero duration, automatic end update, manual override preservation and clearing start without dropping existing end. Existing campaign dates are never rewritten by a mount effect; no server hard constraint was added.</li><li>Scoped ESLint and Vite production bundle PASS. Package/Campaign/common vi/en key parity and diff whitespace PASS. Global app type-check still reports the same 12 baseline errors in content-writing/useTaskContentSync, editor/MediaDropzone, workspace/dashboard and AppRoutes unused imports; no new errors in this slice. Do not report full npm build/type-check as passing.</li><li>Root cause scroll: PageWrapper wraps children in a non-flex body div; previous grid had no bounded height under overflow-hidden Layout. Only task-approvals opts its wrapper body into flex/min-h-0 and a minmax(0,1fr) grid row; shared PageWrapper/Layout unchanged.</li><li>UI/UX skill used for contextual disclosure, keyboard/touch help and hierarchy; existing tokens/primitives retained. React guidance keeps date calculation event-driven, not a resetting effect. API/media traffic was intercepted in Playwright CLI session compact19 on separate Vite 3012; no backend, SQL/Atlas, publisher/Yjs, seeding or shared data edits. Artifacts under output/playwright/compact19-* are ignored local verification, never src tests. No commit/push.</li><li>An unrelated dirty Approval migration was observed at final status; preserved untouched and not executed. Scope audit does not claim the entire workspace is clean.</li></ul><table tabindex="0"><thead><tr><th>Case</th><th>Expected</th></tr></thead><tbody><tr><td>Owner catalogue</td><td>Search/filter without mutation; detail/copy/availability actions preserved</td></tr><tr><td>Client selection</td><td>Only Agency-available packages; existing package-switch lock retained</td></tr><tr><td>Create/copy form</td><td>Existing payload, validation and loading; dirty close asks before discard</td></tr><tr><td>Negotiation</td><td>Client-locked fields unchanged; latest terms/proposal count/two approvals visible</td></tr><tr><td>Package differences</td><td>Old/new business labels, changed text badge, mobile stacking and long text wrapping</td></tr><tr><td>Package approved</td><td>Link to unique Campaign; no embedded duplicate editor</td></tr><tr><td>Campaign plan</td><td>Existing create/edit/save payloads; milestones and work items distinct</td></tr><tr><td>Campaign review</td><td>Correct version, dual approval, Client feedback; structured version comparison</td></tr><tr><td>Deployment</td><td>Existing pending/failure/retry/progress/completion reason behavior retained</td></tr><tr><td>Chat</td><td>History/day groups/sender/time/context/delivery; no raw HTML; Enter/Shift+Enter unchanged</td></tr><tr><td>Disconnected chat</td><td>Visible connection feedback; no fabricated online/member/read states</td></tr><tr><td>vi/en and light/dark</td><td>Parallel keys, readable states, no missing-key labels</td></tr><tr><td>375/768/1440px</td><td>No horizontal page overflow, focus visible, controls reachable</td></tr><tr><td>Scope regression</td><td>Shared UI/layout/theme/routes/access, services/hooks and partner UI untouched</td></tr></tbody></table><h2 id="execution-evidence-—-2026-10-11" tabindex="-1">Execution evidence — 2026-10-11 <a class="header-anchor" href="#execution-evidence-—-2026-10-11" aria-label="Permalink to &quot;Execution evidence — 2026-10-11&quot;">​</a></h2><ul><li><code>npm run type-check</code>: passed.</li><li><code>npm run lint</code>: passed with 0 errors and 81 warnings repository-wide during this slice. Final scoped ESLint on Package/Campaign/Chat: 0 errors, 1 existing <code>react-hooks/set-state-in-effect</code> warning in NegotiateTermsModal&#39;s initialization effect.</li><li><code>npm run build</code>: passed (Vite 8.3.1). Existing ineffective dynamic-import warning concerns mockContentLibraryService in the unrelated Library module.</li><li>Existing Playwright suites: <strong>29/30 passed</strong>, including <strong>12/12 Campaign Partners</strong>. Commands: <code>npx playwright test tests/e2e/media-package tests/e2e/campaign-partners --workers=2 --reporter=list</code>.</li><li>JSON key parity: mediaPackage 184, campaign 132, chat 26 keys; vi/en match.</li><li><code>git diff --check</code>: passed; CRLF conversion notices are not whitespace errors.</li></ul><h3 id="browser-only-checks" tabindex="-1">Browser-only checks <a class="header-anchor" href="#browser-only-checks" aria-label="Permalink to &quot;Browser-only checks&quot;">​</a></h3><p>All API and WebSocket traffic in the CLI audit was intercepted with fixtures; no accounts, seeds, real approvals, deployments or Campaign completion were created.</p><ul><li>Package responsive checks passed at 375/768/1440px in light/dark through the existing suite. Catalogue create/copy, selection, hard gate and stale-save cases passed.</li><li>Chat and Campaign CLI matrix: 12 page/width/theme combinations, no horizontal page overflow and no uncaught page errors. Client Campaign edit controls absent.</li><li>Approved Package links to the separate Campaign page; no embedded Campaign editor.</li><li>English switch renders the approved-package Campaign link correctly.</li><li>Client negotiation: model/max changes/unit remain disabled; changing quantity 12 → 16 then cancelling and keeping editing preserves 16. Mock submission reaches the proposal limit, shows guidance and disables another proposal.</li><li>Package detail opens and closes with Escape.</li><li>Chat: connected status, date groups, message roles/context and composer visible. Shift+Enter inserts a newline; Enter sends. Mock server rejection displays failed delivery. Simulated socket loss displays reconnecting and disables composer.</li><li>Campaign progress fixture displays accessible progress 0/1 correctly.</li></ul><p>CLI scripts and screenshots are local artifacts under <code>brandhub-web/output/playwright/ui-refresh/</code>; generated browser logs are under <code>brandhub-web/.playwright-cli/</code>. They are not application runtime fixtures.</p><h3 id="known-failing-regression-and-boundaries" tabindex="-1">Known failing regression and boundaries <a class="header-anchor" href="#known-failing-regression-and-boundaries" aria-label="Permalink to &quot;Known failing regression and boundaries&quot;">​</a></h3><p><code>media-package.spec.ts:435</code> expects cold navigation to <code>/media-package</code> to reach the Workspace-scoped page, but receives <code>/dashboard</code>. Inspection of shared <code>src/components/layout/AuthGuard.tsx</code> shows <code>/media-package</code> is absent from its legacy Workspace route list; the access check can reject the shortcut before WorkspaceScopedRedirect mounts. Neither file was changed by this UI refresh. Direct <code>/workspaces/{id}/media-package</code> and scoped hard-gate tests pass. A shared guard fix is deliberately deferred outside the approved UI scope.</p><p>API/backend/database, existing services and transport hooks were not modified. Pre-existing E50-09 partner routes/sidebar/access/locale changes remain preserved. Browser fixtures do not replace live end-to-end verification with the running backend. Older-history scroll anchoring and reload/tab-close warnings are implemented but were not separately exercised in the browser audit.</p><h2 id="correction-cases-—-2026-10-11" tabindex="-1">Correction cases — 2026-10-11 <a class="header-anchor" href="#correction-cases-—-2026-10-11" aria-label="Permalink to &quot;Correction cases — 2026-10-11&quot;">​</a></h2><ul><li>Campaign form: milestone section uses “Tên mốc”, work-item section uses “Tên đầu việc”; English has separate labels too. No combined “Tên đầu việc / mốc” label. Adding/removing a milestone must not change workItems and vice versa; saved timeline.milestones and workItems retain their existing structure. Keep sections readable in both themes at 375/768/1440px.</li><li>Owner catalogue at 375/768/1440px, light/dark: search/filter controls have usable width, do not overlap, result count stays together; both search and filter work.</li><li>Vietnamese approval: no “Dual Approval”, “(Client)” or “(Manager)” in Package approval area; Campaign approval uses Vietnamese role labels.</li><li>URL Workspace MANAGER with stale/missing current role: valid DRAFT exposes edit, opens populated form and saves through the existing update API/version contract.</li><li>Client on the same draft: no edit button.</li><li>Manager on APPROVED/IN_PROGRESS/COMPLETED: disabled edit and visible explanation; no update API request. Legacy data stays guarded, no silent conversion.</li><li>User-approved single draft correction: before DRAFT v1, package v3, frozen snapshot equals approved terms, 0 deliverables/0 work items; after 2 snapshot deliverables, same status/version/approvals/work items. Only the exact Campaign/Workspace may match.</li></ul><h3 id="correction-results" tabindex="-1">Correction results <a class="header-anchor" href="#correction-results" aria-label="Permalink to &quot;Correction results&quot;">​</a></h3><ul><li>Milestone/work-item clarification: CLI mock audit passed independent add/remove, edited names and existing save payload structure; separate vi/en labels verified. Both named sections remained separate with no horizontal overflow at 375/768/1440px in light/dark (6 cases). TypeScript app/node checks, scoped ESLint, Vite build and campaign locale key parity passed. No backend or database writes. Local artifacts: <code>output/playwright/ui-refresh/audit-milestones.js</code> and <code>milestones-*.png</code>.</li><li>Owner toolbar: 6 width/theme cases passed. Search/filter widths respectively 343/343px (375 viewport), 267/320px (768), 448/320px (1440). No overlap or horizontal overflow after shared breakpoint transitions settle. Search and hidden filter work.</li><li>Vietnamese approval: heading “Phê duyệt hai bên”, “Phía khách hàng” and “Phía công ty truyền thông”; no parenthesized English approval/role labels in the audited area.</li><li>Mock Manager: URL Workspace role remains authoritative despite a stale selected Client role. Opening populated form and saving issues one PATCH with expectedVersion; new contentVersion is rendered. Client edit controls remain absent.</li><li>APPROVED/IN_PROGRESS/COMPLETED: disabled edit button and explanatory copy verified.</li><li>CLI correction audit: no uncaught page errors. Screenshots/scripts under the same local output/playwright/ui-refresh directory (owner-corrected-* and audit-corrections.js).</li><li>Type-check, targeted ESLint and build passed. vi/en key parity passed. Existing suites rerun: 29/30, same unscoped-shortcut failure; all 12 partner cases passed.</li></ul><h3 id="explicitly-approved-local-data-repair" tabindex="-1">Explicitly approved local data repair <a class="header-anchor" href="#explicitly-approved-local-data-repair" aria-label="Permalink to &quot;Explicitly approved local data repair&quot;">​</a></h3><p>Actual cause for Workspace <code>b84bd2d0-b069-44e9-95e1-1f7b5bc8111d</code>: Campaign <code>d366c84e-93c3-41c8-b433-5bab58a14341</code> was DRAFT v1 with an empty deliverable_plan, triggering the legacy guard. Snapshot v3 equalled approved Workspace terms and contained 2 DELIVERABLE_BUNDLE deliverables; this was not a monthly conversion.</p><p>After explicit user approval, one conditional UPDATE restored deliverable_plan from that exact Campaign snapshot. PostgreSQL reported UPDATE 1. Post-check confirmed DRAFT/content_version=1/package_terms_version=3, 2 deliverables matching snapshot, 0 work items, both approval timestamps still NULL. Internal row_version advanced 0 → 1 for optimistic locking; no business content-version increment, schema change, deployment or Task creation. No other Workspace was updated. Live save through the user&#39;s authenticated browser was not exercised; refresh that Workspace to re-test.</p>',22)])])}const g=a(o,[["render",n]]);export{u as __pageData,g as default};
